#!/bin/sh
# Rebuilds repo-genignored (F3): the defect lives in a GENERATED source that
# .gitignore hides from git.
set -e
D="$(cd "$(dirname "$0")/.." && pwd)"
rm -rf "$D/repo-genignored"; mkdir -p "$D/repo-genignored"; cd "$D/repo-genignored"
cat > gen_rates.py <<'EOF'
# GENERATED by tools/gen_rates.py at build time. Do not edit; regenerate.
def rate_for(days):
    if days >= 30:
        return 25
    return 0
EOF
cat > test_rates.py <<'EOF'
from gen_rates import rate_for


def test_rate_for():
    assert rate_for(31) == 25
    assert rate_for(30) == 0
    assert rate_for(0) == 0
EOF
printf 'gen_rates.py\n__pycache__/\n.fluidfix/\n' > .gitignore
git init -q .; git config user.name u; git config user.email u@e.invalid
git add .gitignore test_rates.py
git commit -q -m "initial (gen_rates.py is generated and gitignored)"
echo "--- gen_rates.py is ignored: $(git check-ignore -v gen_rates.py) ---"
echo "--- now run: ---"
echo "  $D/bin/tmo 300 /Users/kanchetidevieswar/neo/fluidfix/.venv/bin/fluidfix guard . --commit --budget 120"
echo "  # expect: 'repaired line 3' + 'tree already matches last commit — nothing to commit', exit 0"
